function validate([source, target, original, changed, cost]) {
  const lower = /^[a-z]+$/;
  if (source.length < 1 || source.length > 1000) return 'source needs 1 to 1000 letters.';
  if (target.length !== source.length) return 'source and target must have the same length.';
  if (!lower.test(source) || !lower.test(target)) return 'source and target use only lowercase letters.';
  const m = original.length;
  if (m < 1 || m > 100) return 'There must be 1 to 100 rules.';
  if (changed.length !== m || cost.length !== m) return 'original, changed and cost must have the same length.';
  for (let i = 0; i < m; i++) {
    if (typeof original[i] !== 'string' || typeof changed[i] !== 'string') return 'Each rule rewrites one string into another.';
    if (original[i].length !== changed[i].length) return 'original[i] and changed[i] must have the same length.';
    if (original[i].length < 1 || original[i].length > source.length) return 'Rule strings have 1 to source.length letters.';
    if (!lower.test(original[i]) || !lower.test(changed[i])) return 'Rule strings use only lowercase letters.';
    if (original[i] === changed[i]) return 'original[i] must differ from changed[i].';
    if (!Number.isInteger(cost[i]) || cost[i] < 1 || cost[i] > 1e6) return 'Each cost is an integer between 1 and 10^6.';
  }
  return null;
}

