function minimumCost(source, target, original, changed, cost) {
  const root = { children: new Map(), id: -1 };
  let count = 0;
  const insert = (word) => {
    let node = root;
    for (const letter of word) {
      if (!node.children.has(letter)) {
        node.children.set(letter, { children: new Map(), id: -1 });
      }
      node = node.children.get(letter);
    }
    if (node.id === -1) {
      node.id = count++;
    }
    return node.id;
  };
  const edges = original.map((word, i) => [insert(word), insert(changed[i]), cost[i]]);

  const dist = Array.from({ length: count }, () => new Array(count).fill(Infinity));
  for (let id = 0; id < count; id++) {
    dist[id][id] = 0;
  }
  for (const [from, to, price] of edges) {
    dist[from][to] = Math.min(dist[from][to], price);
  }
  for (let mid = 0; mid < count; mid++) {
    for (let from = 0; from < count; from++) {
      for (let to = 0; to < count; to++) {
        if (dist[from][mid] + dist[mid][to] < dist[from][to]) {
          dist[from][to] = dist[from][mid] + dist[mid][to];
        }
      }
    }
  }

  const n = source.length;
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;
  for (let start = 0; start < n; start++) {
    if (dp[start] === Infinity) {
      continue;
    }
    if (source[start] === target[start]) {
      dp[start + 1] = Math.min(dp[start + 1], dp[start]);
    }
    let fromNode = root;
    let toNode = root;
    for (let end = start; end < n; end++) {
      fromNode = fromNode.children.get(source[end]);
      toNode = toNode.children.get(target[end]);
      if (!fromNode || !toNode) {
        break;
      }
      if (fromNode.id !== -1 && toNode.id !== -1) {
        dp[end + 1] = Math.min(dp[end + 1], dp[start] + dist[fromNode.id][toNode.id]);
      }
    }
  }
  return dp[n] === Infinity ? -1 : dp[n];
}

