function minimumCost(source, target, original, changed, cost) {
  // Cheapest rewrite of x into y, found by relaxing every rule until nothing improves.
  const convert = (x, y) => {
    if (x === y) return 0;
    const best = new Map([[x, 0]]);
    let improved = true;
    while (improved) {
      improved = false;
      for (let i = 0; i < original.length; i++) {
        if (!best.has(original[i])) continue;
        const price = best.get(original[i]) + cost[i];
        if (price < (best.has(changed[i]) ? best.get(changed[i]) : Infinity)) { best.set(changed[i], price); improved = true; }
      }
    }
    return best.has(y) ? best.get(y) : Infinity;
  };
  const n = source.length;
  const suffix = new Array(n + 1).fill(Infinity);
  suffix[n] = 0;
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j <= n; j++) {
      const price = convert(source.slice(i, j), target.slice(i, j));
      if (price + suffix[j] < suffix[i]) suffix[i] = price + suffix[j];
    }
  }
  return suffix[0] === Infinity ? -1 : suffix[0];
}

