function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? 'abcde' : rand() < 0.5 ? 'ab' : 'abc';
  const word = (len) => Array.from({ length: len }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const pickFrom = (list) => list[Math.floor(rand() * list.length)];
  const n = large ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 7);
  const source = word(n);
  const m = large ? 100 : 1 + Math.floor(rand() * 6);
  const original = [], changed = [], cost = [];
  for (let i = 0; i < m; i++) {
    const longRule = large && rand() < 0.05;
    const len = Math.min(n, longRule ? 30 + Math.floor(rand() * 70) : 1 + Math.floor(rand() * (large ? 10 : 3)));
    const roll = rand();
    const sameLength = changed.filter(w => w.length === len);
    let from;
    if (roll < 0.45) {
      const start = Math.floor(rand() * (n - len + 1));
      from = source.slice(start, start + len);
    } else if (roll < 0.8 && sameLength.length) {
      from = pickFrom(sameLength);
    } else {
      from = word(len);
    }
    let to = word(len);
    while (to === from) to = word(len);
    original.push(from);
    changed.push(to);
    cost.push(1 + Math.floor(rand() * (large ? 1e6 : 20)));
  }
  // Build target by applying chains of rules on separate pieces of source, plus a little noise.
  const noise = rand() < 0.35 ? (large ? 0.003 : 0.2) : 0;
  let target = '';
  for (let i = 0; i < n;) {
    const options = original.map((_, k) => k).filter(k => source.startsWith(original[k], i));
    if (options.length && rand() < 0.7) {
      let current = changed[pickFrom(options)];
      while (rand() < 0.5) {
        const next = original.map((_, k) => k).filter(k => original[k] === current);
        if (!next.length) break;
        current = changed[pickFrom(next)];
      }
      target += current;
      i += current.length;
    } else {
      let letter = source[i];
      if (rand() < noise) while (letter === source[i]) letter = word(1);
      target += letter;
      i++;
    }
  }
  return [source, target, original, changed, cost];
}
